#[test]fn synthetic_candidate_actual_zip_reopen_and_no_clobber(){
    let(p,m)=fixture();let changes=transform(&p,&m).unwrap();let mut source=ZipWriter::new(Cursor::new(vec![]));
    for(n,e)in &p{source.start_file(n,SimpleFileOptions::default().compression_method(e.method)).unwrap();source.write_all(&e.data).unwrap();}
    let bytes=originize_all_protected(&source.finish().unwrap().into_inner());let original=package(&bytes).unwrap();assert_eq!(original.values().filter(|e|e.unix.is_none()).count(),8);let before=hash(&bytes);let mut out=Cursor::new(vec![]);write_zip(&bytes,&changes,&mut out).unwrap();let candidate=package(out.get_ref()).unwrap();let(preserved,_)=verify(&original,&candidate,&m,&changes).unwrap();assert_eq!(preserved.len(),8);assert!(original.iter().any(|(n,e)|!changes.contains_key(n)&&e.central[42..46]!=candidate[n].central[42..46]),"protected offsets actually relocated");assert_eq!(candidate.values().filter(|e|e.unix.is_none()).count(),8);assert_eq!(before,hash(&bytes));assert!(no_clobber_decision(false,true,true).is_ok());assert!(no_clobber_decision(true,true,true).is_err()); // pure pre-existing/race-created decision; persist_noclobber remains unchanged
}
